:root {
  --bg-watermark: light-dark(url("chrome://messenger/skin/images/account-watermark.png"), url("chrome://messenger/skin/images/account-watermark-light.png"));
}

[hidden] {
  display: none !important; /* Ensure flex items obey hidden="hidden". */
}

:focus-visible {
  outline: 2px solid var(--focus-outline-color);
}

body {
  /* Overwrite rules in messenger.css. */
  display: block;
  overflow: auto;
  margin: 0;
  block-size: 100vh;
  background-color: var(--layout-background-0);
  text-shadow: none;
}

#accountCentral {
  display: flex;
  flex-direction: column;
  background-image: var(--bg-watermark);
  background-position: bottom right;
  background-repeat: no-repeat;
  color: var(--color-text-base);
